-- Phase 1 initial schema. Execute once; future changes require versioned migrations.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), email text UNIQUE NOT NULL, locale text NOT NULL DEFAULT 'en' CHECK(locale IN ('en','pl','de')), timezone text NOT NULL DEFAULT 'UTC', tier text NOT NULL DEFAULT 'free', deleted_at timestamptz);
CREATE TABLE auth_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, provider_subject text NOT NULL, UNIQUE(provider,provider_subject));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE consents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, version text NOT NULL, locale text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,version));
CREATE TABLE credentials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, key_id text NOT NULL, ciphertext bytea NOT NULL, nonce bytea NOT NULL CHECK(octet_length(nonce)=12), tag bytea NOT NULL CHECK(octet_length(tag)=16), UNIQUE(user_id,provider));
CREATE TABLE watchlists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL);
CREATE TABLE watchlist_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), watchlist_id uuid NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE, venue text NOT NULL, market text NOT NULL, symbol text NOT NULL, UNIQUE(watchlist_id,venue,market,symbol));
CREATE TABLE drawings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, venue text NOT NULL, market text NOT NULL, symbol text NOT NULL, timeframe text NOT NULL, kind text NOT NULL, payload jsonb NOT NULL, version integer NOT NULL DEFAULT 1, deleted_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE indicator_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, config jsonb NOT NULL);
CREATE TABLE market_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), venue text NOT NULL, market text NOT NULL, symbol text NOT NULL, timeframe text NOT NULL, observed_at timestamptz NOT NULL, snapshot_hash text UNIQUE NOT NULL, data jsonb NOT NULL, schema_version integer NOT NULL);
CREATE TABLE analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, snapshot_id uuid REFERENCES market_snapshots(id), locale text NOT NULL, provider text NOT NULL, model text NOT NULL, prompt_version text NOT NULL, schema_version integer NOT NULL, status text NOT NULL CHECK(status IN ('queued','running','completed','failed')), result jsonb, cost_usd numeric(18,8), idempotency_key text NOT NULL, UNIQUE(user_id,idempotency_key));
CREATE TABLE signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), analysis_id uuid NOT NULL REFERENCES analyses(id) ON DELETE CASCADE, direction text NOT NULL CHECK(direction IN ('LONG','SHORT')), entry numeric(30,12) NOT NULL, stop_loss numeric(30,12) NOT NULL, targets jsonb NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','tp','sl','expired','ambiguous')), evaluation jsonb);
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, condition jsonb NOT NULL, channels jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true, last_triggered_at timestamptz);
CREATE TABLE notification_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), alert_id uuid NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, channel text NOT NULL, event_key text NOT NULL, status text NOT NULL, attempts integer NOT NULL DEFAULT 0, UNIQUE(alert_id,channel,event_key));
CREATE TABLE paper_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE, balance numeric(30,12) NOT NULL CHECK(balance>=0), currency text NOT NULL DEFAULT 'USD', version integer NOT NULL DEFAULT 1);
CREATE TABLE paper_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), account_id uuid NOT NULL REFERENCES paper_accounts(id) ON DELETE CASCADE, symbol text NOT NULL, direction text NOT NULL, quantity numeric(30,12) NOT NULL CHECK(quantity>0), order_type text NOT NULL, limit_price numeric(30,12), fill_price numeric(30,12), fees numeric(30,12), status text NOT NULL, idempotency_key text NOT NULL, UNIQUE(account_id,idempotency_key));
CREATE TABLE journal_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, symbol text NOT NULL, entry numeric(30,12), exit numeric(30,12), quantity numeric(30,12), fees numeric(30,12), notes text, attachment_keys jsonb);
CREATE TABLE backtests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, strategy jsonb NOT NULL, dataset_hash text, status text NOT NULL, result jsonb);
CREATE TABLE subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, stripe_customer_id text UNIQUE, stripe_subscription_id text UNIQUE, status text NOT NULL, current_period_end timestamptz);
CREATE TABLE usage_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, analysis_id uuid REFERENCES analyses(id) ON DELETE CASCADE, input_tokens integer NOT NULL, output_tokens integer NOT NULL, cost_usd numeric(18,8) NOT NULL);
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, resource_id uuid, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE candles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), venue text NOT NULL, market text NOT NULL, symbol text NOT NULL, timeframe text NOT NULL, open_time timestamptz NOT NULL, open numeric(30,12) NOT NULL, high numeric(30,12) NOT NULL, low numeric(30,12) NOT NULL, close numeric(30,12) NOT NULL, volume numeric(30,12) NOT NULL CHECK(volume>=0), closed boolean NOT NULL, CHECK(high>=low AND high>=open AND high>=close AND low<=open AND low<=close), UNIQUE(venue,market,symbol,timeframe,open_time));
CREATE INDEX auth_accounts_user_idx ON auth_accounts(user_id);
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX consents_user_idx ON consents(user_id);
CREATE INDEX credentials_user_idx ON credentials(user_id);
CREATE INDEX watchlists_user_idx ON watchlists(user_id);
CREATE INDEX drawings_user_idx ON drawings(user_id);
CREATE INDEX indicator_templates_user_idx ON indicator_templates(user_id);
CREATE INDEX analyses_user_idx ON analyses(user_id);
CREATE INDEX alerts_user_idx ON alerts(user_id);
CREATE INDEX paper_accounts_user_idx ON paper_accounts(user_id);
CREATE INDEX journal_entries_user_idx ON journal_entries(user_id);
CREATE INDEX backtests_user_idx ON backtests(user_id);
CREATE INDEX subscriptions_user_idx ON subscriptions(user_id);
CREATE INDEX usage_events_user_idx ON usage_events(user_id);
CREATE INDEX audit_logs_user_idx ON audit_logs(user_id);
CREATE INDEX drawings_lookup_idx ON drawings(user_id,venue,market,symbol,timeframe);
CREATE INDEX signals_pending_idx ON signals(status,expires_at);
CREATE INDEX analyses_status_idx ON analyses(status,created_at);
COMMIT;
